CREATE TYPE "QrCheckoutOrderStatus" AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED');
CREATE TABLE "qr_checkout_links" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"name" VARCHAR(160) NOT NULL,"token" VARCHAR(80) NOT NULL,"delivery_enabled" BOOLEAN NOT NULL DEFAULT false,"address_required" BOOLEAN NOT NULL DEFAULT false,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "qr_checkout_links_pkey" PRIMARY KEY("id"),CONSTRAINT "qr_checkout_links_tenant_id_fkey" FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "qr_checkout_links_token_key" ON "qr_checkout_links"("token"); CREATE INDEX "qr_checkout_links_tenant_id_active_idx" ON "qr_checkout_links"("tenant_id","active");
CREATE TABLE "qr_checkout_offers" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"link_id" UUID NOT NULL,"product_id" UUID,"title" VARCHAR(180) NOT NULL,"description" TEXT,"price" DECIMAL(14,2) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "qr_checkout_offers_pkey" PRIMARY KEY("id"),CONSTRAINT "qr_checkout_offers_link_id_fkey" FOREIGN KEY("link_id") REFERENCES "qr_checkout_links"("id") ON DELETE CASCADE,CONSTRAINT "qr_checkout_offers_product_id_fkey" FOREIGN KEY("product_id") REFERENCES "products"("id") ON DELETE SET NULL);
CREATE INDEX "qr_checkout_offers_link_id_active_idx" ON "qr_checkout_offers"("link_id","active");
CREATE TABLE "qr_checkout_orders" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"tenant_id" UUID NOT NULL,"link_id" UUID NOT NULL,"external_reference" TEXT NOT NULL,"provider_payment_id" TEXT,"buyer_name" VARCHAR(160) NOT NULL,"buyer_email" VARCHAR(320),"buyer_phone" VARCHAR(40),"delivery_address" TEXT,"total" DECIMAL(14,2) NOT NULL,"status" "QrCheckoutOrderStatus" NOT NULL DEFAULT 'PENDING',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"paid_at" TIMESTAMP(3),CONSTRAINT "qr_checkout_orders_pkey" PRIMARY KEY("id"),CONSTRAINT "qr_checkout_orders_tenant_id_fkey" FOREIGN KEY("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE,CONSTRAINT "qr_checkout_orders_link_id_fkey" FOREIGN KEY("link_id") REFERENCES "qr_checkout_links"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "qr_checkout_orders_external_reference_key" ON "qr_checkout_orders"("external_reference"); CREATE INDEX "qr_checkout_orders_tenant_id_status_created_at_idx" ON "qr_checkout_orders"("tenant_id","status","created_at");
CREATE TABLE "qr_checkout_order_items" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"order_id" UUID NOT NULL,"offer_id" UUID NOT NULL,"product_id" UUID,"title" VARCHAR(180) NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 1,"unit_price" DECIMAL(14,2) NOT NULL,"total" DECIMAL(14,2) NOT NULL,CONSTRAINT "qr_checkout_order_items_pkey" PRIMARY KEY("id"),CONSTRAINT "qr_checkout_order_items_order_id_fkey" FOREIGN KEY("order_id") REFERENCES "qr_checkout_orders"("id") ON DELETE CASCADE,CONSTRAINT "qr_checkout_order_items_offer_id_fkey" FOREIGN KEY("offer_id") REFERENCES "qr_checkout_offers"("id"));
CREATE INDEX "qr_checkout_order_items_order_id_idx" ON "qr_checkout_order_items"("order_id");
-- Rollback: DROP TABLE "qr_checkout_order_items","qr_checkout_orders","qr_checkout_offers","qr_checkout_links"; DROP TYPE "QrCheckoutOrderStatus";
